use vstd::prelude::*;

verus! {

// Helper specification function to check if an index contains the maximum value
spec fn is_max_index(a: Seq<i32>, idx: int) -> bool {
    0 <= idx < a.len() &&
    forall|i: int| 0 <= i < a.len() ==> a[i] <= a[idx]
}

fn findMax(a: &[i32], n: usize) -> (result: usize)
    requires
        n == a@.len(),
        n > 0,
    ensures
        result < n,
        is_max_index(a@, result as int),
{
    // Initialize max_index to 0, since n > 0, this is safe
    let mut max_index: usize = 0;
    
    for i in 1..n
        invariant
            n == a@.len(),
            n > 0,
            max_index < n,
            // max_index points to the maximum element in a[0..i]
            forall|j: int| 0 <= j < i ==> a@[j] <= a@[max_index as int],
            // max_index is within the range we've seen so far
            0 <= max_index < i,
    {
        if a[i] > a[max_index] {
            max_index = i;
        }
        
        // Assertion to help the verifier understand that after the update,
        // max_index still points to the maximum in a[0..i+1]
        assert(forall|j: int| 0 <= j < i + 1 ==> a@[j] <= a@[max_index as int]);
    }
    
    // After the loop, we've seen all elements a[0..n]
    assert(forall|j: int| 0 <= j < n ==> a@[j] <= a@[max_index as int]);
    
    max_index
}

} // verus!